227	    /// Read a window off of the application context.
228	    fn read_window<T, R>(
229	        &self,
230	        window: &WindowHandle<T>,
231	        read: impl FnOnce(Entity<T>, &App) -> R,
232	    ) -> Result<R>
233	    where
234	        T: 'static;
